`timescale 1ns/1ps
// Exact-code scoreboard for the atomic source-major 4x4 HC stable-softmax.
// Expected words are generated by an independent exact-rational oracle.  The
// controller cycles counted here are verification cost, not architectural
// model latency and not TPOT.
module tb_a3_hc_stable_softmax;
    localparam integer CASE_MAX = 900;
    localparam integer INPUT_WORDS = 16;
    localparam integer EXPECTED_WORDS = 17;
    localparam integer TIMEOUT_CYCLES = 4096;

    reg clk;
    reg rst_n;
    reg in_valid;
    wire in_ready;
    reg [511:0] matrix_codes;
    wire out_valid;
    reg out_ready;
    wire [511:0] result_codes;
    wire [1:0] result_error;

    reg [31:0] meta [0:7];
    reg [31:0] matrix_inputs [0:CASE_MAX*INPUT_WORDS-1];
    reg [31:0] matrix_expected [0:CASE_MAX*EXPECTED_WORDS-1];
    reg [2047:0] meta_path;
    reg [2047:0] input_path;
    reg [2047:0] expected_path;

    integer cases;
    integer checkpoint_cases;
    integer directed_cases;
    integer expected_successes;
    integer expected_errors;
    integer t1_case;
    integer case_index;
    integer word_index;
    integer failures;
    integer checks;
    integer successes;
    integer errors;
    integer argument_errors;
    integer overflow_errors;
    integer checkpoint_words;
    integer t1_words;
    integer busy_refusals;
    integer output_stalls;
    integer maximum_cycles;
    integer reset_cycles;
    integer atomic_busy_checks;

    ot_a3_hc_stable_softmax_rne dut (
        .clk(clk),
        .rst_n(rst_n),
        .in_valid(in_valid),
        .in_ready(in_ready),
        .matrix_codes(matrix_codes),
        .out_valid(out_valid),
        .out_ready(out_ready),
        .result_codes(result_codes),
        .result_error(result_error)
    );

    always #5 clk = ~clk;

    task automatic tick;
        begin
            @(posedge clk);
            #1;
        end
    endtask

    task automatic expect_equal;
        input [255:0] label;
        input [511:0] got;
        input [511:0] wanted;
        begin
            checks = checks + 1;
            if (got !== wanted) begin
                failures = failures + 1;
                if (failures <= 24)
                    $display(
                        "FAIL case=%0d %0s got=%h wanted=%h",
                        case_index, label, got, wanted
                    );
            end
        end
    endtask

    task automatic load_input;
        input integer index;
        integer item;
        begin
            for (item = 0; item < INPUT_WORDS; item = item + 1)
                matrix_codes[32*item +: 32] =
                    matrix_inputs[index*INPUT_WORDS + item];
        end
    endtask

    task automatic check_private_output;
        begin
            expect_equal("busy has no architectural valid", out_valid, 0);
            expect_equal("busy has no partial matrix", result_codes, 0);
            atomic_busy_checks = atomic_busy_checks + 2;
        end
    endtask

    task automatic run_case;
        input integer index;
        integer expected_base;
        integer cycles;
        integer hold_cycles;
        integer attempt;
        integer item;
        reg [1:0] wanted_error;
        reg [511:0] held_result;
        reg [1:0] held_error;
        begin
            case_index = index;
            expected_base = index * EXPECTED_WORDS;
            wanted_error = matrix_expected[expected_base + 16][1:0];
            out_ready = 1'b0;
            in_valid = 1'b0;
            repeat (index % 2)
                tick();
            while (!in_ready)
                tick();

            load_input(index);
            in_valid = 1'b1;
            tick();
            in_valid = 1'b0;
            cycles = 1;

            // For every non-immediate request, replace the live input bus with
            // poison and attempt a second transaction.  Only the accepted
            // private input matrix may influence the result.
            if (wanted_error != 2'd1) begin
                in_valid = 1'b1;
                matrix_codes = {16{32'h7fc0_0001}};
                for (attempt = 0; attempt < 2; attempt = attempt + 1) begin
                    expect_equal("busy input refusal", in_ready, 0);
                    busy_refusals = busy_refusals + 1;
                    check_private_output();
                    tick();
                    cycles = cycles + 1;
                end
                in_valid = 1'b0;
            end

            while (!out_valid && cycles < TIMEOUT_CYCLES) begin
                check_private_output();
                tick();
                cycles = cycles + 1;
            end
            expect_equal("bounded completion", out_valid, 1);
            if (cycles > maximum_cycles)
                maximum_cycles = cycles;
            expect_equal("result error", result_error, wanted_error);
            if (wanted_error == 0)
                successes = successes + 1;
            else begin
                errors = errors + 1;
                if (wanted_error == 1)
                    argument_errors = argument_errors + 1;
                else if (wanted_error == 2)
                    overflow_errors = overflow_errors + 1;
            end
            for (item = 0; item < INPUT_WORDS; item = item + 1) begin
                expect_equal(
                    "stable-softmax output word",
                    result_codes[32*item +: 32],
                    matrix_expected[expected_base + item]
                );
                if (index < checkpoint_cases)
                    checkpoint_words = checkpoint_words + 1;
                if (index == t1_case)
                    t1_words = t1_words + 1;
            end
            if (wanted_error != 0)
                expect_equal("failure is atomically all zero", result_codes, 0);

            held_result = result_codes;
            held_error = result_error;
            hold_cycles = (index % 19 == 0) ? 3 :
                          (index % 7 == 0) ? 1 : 0;
            for (attempt = 0; attempt < hold_cycles; attempt = attempt + 1) begin
                tick();
                expect_equal("stalled output valid", out_valid, 1);
                expect_equal("stalled output matrix", result_codes, held_result);
                expect_equal("stalled output error", result_error, held_error);
                expect_equal("stalled output refuses input", in_ready, 0);
                output_stalls = output_stalls + 1;
            end
            out_ready = 1'b1;
            tick();
            out_ready = 1'b0;
            expect_equal("output consumed", out_valid, 0);
        end
    endtask

    task automatic run_active_reset;
        integer attempt;
        begin
            case_index = -1;
            while (!in_ready)
                tick();
            load_input(0);
            in_valid = 1'b1;
            tick();
            in_valid = 1'b0;
            matrix_codes = {16{32'h7fc0_0001}};
            for (attempt = 0; attempt < 31; attempt = attempt + 1) begin
                expect_equal("reset precondition busy", in_ready, 0);
                check_private_output();
                reset_cycles = reset_cycles + 1;
                tick();
            end
            rst_n = 1'b0;
            #1;
            expect_equal("reset clears valid", out_valid, 0);
            expect_equal("reset clears matrix", result_codes, 0);
            expect_equal("reset clears error", result_error, 0);
            repeat (2)
                tick();
            rst_n = 1'b1;
            #1;
            expect_equal("ready after active reset", in_ready, 1);
        end
    endtask

    initial begin
        clk = 1'b0;
        rst_n = 1'b0;
        in_valid = 1'b0;
        matrix_codes = 0;
        out_ready = 1'b0;
        failures = 0;
        checks = 0;
        successes = 0;
        errors = 0;
        argument_errors = 0;
        overflow_errors = 0;
        checkpoint_words = 0;
        t1_words = 0;
        busy_refusals = 0;
        output_stalls = 0;
        maximum_cycles = 0;
        reset_cycles = 0;
        atomic_busy_checks = 0;
        case_index = -1;

        if (!$value$plusargs("META=%s", meta_path) ||
            !$value$plusargs("INPUT=%s", input_path) ||
            !$value$plusargs("EXPECTED=%s", expected_path))
            $fatal(1, "missing HC stable-softmax vector plusargs");
        $readmemh(meta_path, meta);
        if (meta[0] !== 32'ha3c5_0f7a || meta[1] !== 1)
            $fatal(1, "HC stable-softmax vector metadata mismatch");
        cases = meta[2];
        checkpoint_cases = meta[3];
        directed_cases = meta[4];
        expected_successes = meta[5];
        expected_errors = meta[6];
        t1_case = meta[7];
        if (cases <= 0 || cases > CASE_MAX ||
            checkpoint_cases < 1 || checkpoint_cases > cases ||
            directed_cases != cases - checkpoint_cases ||
            expected_successes + expected_errors != cases ||
            t1_case < 0 || t1_case >= checkpoint_cases)
            $fatal(1, "HC stable-softmax vector counts are malformed");
        $readmemh(
            input_path, matrix_inputs, 0, cases*INPUT_WORDS-1
        );
        $readmemh(
            expected_path, matrix_expected, 0,
            cases*EXPECTED_WORDS-1
        );

        repeat (4)
            tick();
        rst_n = 1'b1;
        repeat (2)
            tick();
        expect_equal("input ready after reset", in_ready, 1);
        expect_equal("output invalid after reset", out_valid, 0);
        expect_equal("matrix zero after reset", result_codes, 0);
        expect_equal("error zero after reset", result_error, 0);

        run_active_reset();
        for (case_index = 0; case_index < cases;
             case_index = case_index + 1)
            run_case(case_index);

        expect_equal("success count", successes, expected_successes);
        expect_equal("error count", errors, expected_errors);
        expect_equal("checkpoint word count", checkpoint_words,
                     checkpoint_cases * INPUT_WORDS);
        expect_equal("T=1 shape word count", t1_words, INPUT_WORDS);

        $display("SOFTMAX_SUMMARY cases=%0d checkpoint=%0d directed=%0d success=%0d errors=%0d argument_errors=%0d overflow_errors=%0d checkpoint_words=%0d t1_words=%0d busy_refusals=%0d stalls=%0d max_cycles=%0d reset_cycles=%0d atomic_busy_checks=%0d",
                 cases, checkpoint_cases, directed_cases, successes, errors,
                 argument_errors, overflow_errors, checkpoint_words, t1_words,
                 busy_refusals, output_stalls, maximum_cycles, reset_cycles,
                 atomic_busy_checks);
        if (failures != 0) begin
            $display("FAIL a3_hc_stable_softmax failures=%0d checks=%0d",
                     failures, checks);
            $fatal(1);
        end
        $display("PASS a3_hc_stable_softmax checks=%0d", checks);
        $finish;
    end
endmodule
